$cs="Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;"; $conn=New-Object System.Data.SqlClient.SqlConnection($cs); $conn.Open(); $cmd=$conn.CreateCommand(); $cmd.CommandText="SELECT EmployeeId, FullName, PrimaryRole, SecondaryRole, IsActive FROM Employees WHERE EmployeeId IN ('4390187','4390267','4390487')"; $r=$cmd.ExecuteReader(); while($r.Read()){Write-Host $r[0] '|' $r[1] '|' $r[2] '|' $r[3] '| Active=' $r[4]}; $conn.Close(); Write-Host "---done---"
